insert into roles values('procurement_manager'),('supplier') on conflict do nothing;
create table public.suppliers(id uuid primary key default gen_random_uuid(),name text not null,legal_entity text not null,country text not null,contact text not null,verification_status text not null default 'pending' check(verification_status in ('pending','verified','suspended')),contract_reference text,quality_notes text,created_by uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.product_categories(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null);
insert into product_categories(slug,name) values('appliances','Appliances'),('phones-computers','Smartphones & computers'),('gadgets','Gadgets'),('accessories','Accessories'),('machinery','Machinery'),('industrial','Industrial equipment'),('tools','Tools'),('devices','Devices'),('vehicles','Vehicles'),('vehicle-accessories','Vehicle accessories');
create table public.catalog_products(id uuid primary key default gen_random_uuid(),sku text not null unique,slug text not null unique,title text not null,category_id uuid not null references product_categories(id),partner_id uuid not null references suppliers(id),listing_type text not null check(listing_type in ('fixed_price','priced_to_order','quote_only')),specs jsonb not null default '{}',origin text not null,condition text not null,warranty text not null,voltage text not null,lead_time text not null,currency text not null default 'NGN' check(currency='NGN'),price_minor bigint check(price_minor>0),price_valid_until timestamptz,status text not null default 'draft' check(status in ('draft','review','published','suspended','recalled')),compliance_flags jsonb not null default '{}',hs_code text not null,import_eligibility text not null,seller_of_record text not null,importer_of_record text not null,warranty_party text not null,partner_roles text not null,created_by uuid not null references profiles(id),reviewed_by uuid references profiles(id),created_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references catalog_products(id),attributes jsonb not null,sku text not null unique);
create table public.inventory(id uuid primary key default gen_random_uuid(),product_id uuid not null unique references catalog_products(id),stock integer not null default 0 check(stock>=0),lead_time text not null,updated_at timestamptz not null default now());
create table public.quotes(id uuid primary key default gen_random_uuid(),customer_id uuid not null references profiles(id),supplier_id uuid references suppliers(id),request_details text not null,requested_items jsonb not null default '[]',status text not null default 'requested' check(status in ('requested','draft','sent','accepted','cancelled','expired')),currency text not null default 'NGN' check(currency='NGN'),supplier_price bigint not null default 0 check(supplier_price>=0),service_margin bigint not null default 0 check(service_margin>=0),export_handling bigint not null default 0 check(export_handling>=0),freight bigint not null default 0 check(freight>=0),insurance bigint not null default 0 check(insurance>=0),duties_taxes bigint not null default 0 check(duties_taxes>=0),clearing bigint not null default 0 check(clearing>=0),domestic_transport bigint not null default 0 check(domestic_transport>=0),inspection bigint not null default 0 check(inspection>=0),total_minor bigint generated always as (supplier_price+service_margin+export_handling+freight+insurance+duties_taxes+clearing+domestic_transport+inspection) stored,fx_rate numeric(18,8),fx_source text,fx_at timestamptz,fx_risk_party text,assumptions text,seller_of_record text,importer_of_record text,warranty_party text,partner_roles text,estimated_window text,terms_version text,expires_at timestamptz,accepted_at timestamptz,created_by uuid references profiles(id),approved_by uuid references profiles(id),created_at timestamptz not null default now());
create table public.quote_lines(id uuid primary key default gen_random_uuid(),quote_id uuid not null references quotes(id),product_id uuid references catalog_products(id),description text not null,quantity integer not null check(quantity>0),unit_price_minor bigint not null check(unit_price_minor>=0));
create table public.orders(id uuid primary key default gen_random_uuid(),reference text not null unique default ('ORD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),buyer_id uuid not null references profiles(id),quote_id uuid not null unique references quotes(id),seller_id uuid not null references suppliers(id),source_partner_id uuid references suppliers(id),assigned_supplier_user uuid references profiles(id),total_minor bigint not null check(total_minor>0),currency text not null default 'NGN' check(currency='NGN'),status text not null default 'payment_pending' check(status in ('payment_pending','payment_verified','procurement_approved','purchased','inspection','in_transit','clearance','delivery','completed','disputed','cancelled','return_requested','returned','refunded','failed_delivery')),delivery jsonb not null,accepted_terms_version text not null,created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),product_id uuid references catalog_products(id),description text not null,quantity int not null check(quantity>0),unit_price_minor bigint not null check(unit_price_minor>=0));
create table public.order_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),status text not null,note text not null,actor_id uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.shipments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),carrier text not null,tracking text not null,milestone text not null,estimated_window text,created_by uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.customs_docs(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),title text not null,private_storage_path text not null,kind text not null check(kind in ('inspection','shipping','customs','invoice','contract')),created_by uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.disputes(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),owner_id uuid not null references profiles(id),kind text not null check(kind in ('dispute','return','cancellation','failed_delivery')),reason text not null,status text not null default 'open' check(status in ('open','investigating','resolved','rejected')),response text,created_at timestamptz not null default now());
create table public.recognition_preferences(user_id uuid primary key references profiles(id),visibility text not null default 'private' check(visibility in ('private','anonymous','public')),public_alias text not null default '',city text not null default '',message text not null default '',recognition_type text not null default 'Community Supporter' check(recognition_type in ('Founding Supporter','Community Supporter','Returning Supporter','Legacy Supporter')),consent_at timestamptz,updated_at timestamptz not null default now(),check(visibility<>'public' or (length(public_alias)>0 and consent_at is not null)));
alter table contribution_intents add column purpose text not null default 'donation' check(purpose in ('donation','order')),add column order_id uuid unique references orders(id),add column campaign_id uuid references campaigns(id),add column restricted_project_id uuid references development_projects(id),add column dedication text not null default '',add column recognition_visibility text not null default 'private' check(recognition_visibility in ('private','anonymous','public'));
alter table contribution_intents add constraint purpose_order check((purpose='donation' and order_id is null) or (purpose='order' and order_id is not null));
alter table contributions add column purpose text not null default 'donation' check(purpose in ('donation','order'));
create table public.transactions(id uuid primary key default gen_random_uuid(),settlement_id uuid not null unique references contributions(id),intent_id uuid not null unique references contribution_intents(id),purpose text not null check(purpose in ('donation','order')),user_id uuid not null references profiles(id),currency text not null check(currency='NGN'),gross_minor bigint not null check(gross_minor>0),net_minor bigint not null check(net_minor>0),method text not null default 'bank_transfer',beneficiary_account uuid not null references bank_accounts(id),reference text not null unique,verified_by uuid not null references profiles(id),verified_at timestamptz not null default now());
create table public.transaction_events(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references transactions(id),event_type text not null check(event_type in ('verified','reversed')),amount_minor bigint not null check(amount_minor>0),actor_id uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.donations(id uuid primary key default gen_random_uuid(),supporter_id uuid not null references profiles(id),transaction_id uuid not null unique references transactions(id),campaign_id uuid references campaigns(id),restricted_project_id uuid references development_projects(id),amount_minor bigint not null check(amount_minor>0),dedication text not null default '',recognition_visibility text not null check(recognition_visibility in ('private','anonymous','public')),created_at timestamptz not null default now());
create table public.order_ledger_entries(id uuid primary key default gen_random_uuid(),settlement_id uuid not null references contributions(id),refund_id uuid references refunds(id),account text not null check(account in ('bank','order_receipts')),debit_minor bigint not null default 0 check(debit_minor>=0),credit_minor bigint not null default 0 check(credit_minor>=0),created_at timestamptz not null default now(),check((debit_minor>0 and credit_minor=0) or (credit_minor>0 and debit_minor=0)));
create table public.donation_allocations(id uuid primary key default gen_random_uuid(),donation_id uuid not null references donations(id),project_id uuid not null references development_projects(id),amount_minor bigint not null check(amount_minor>0),reason text not null,requested_by uuid not null references profiles(id),approved_by uuid references profiles(id),status text not null default 'requested' check(status in ('requested','approved')),created_at timestamptz not null default now(),check(approved_by is null or approved_by<>requested_by));
create table public.expenditures(id uuid primary key default gen_random_uuid(),project_id uuid not null references development_projects(id),allocation_id uuid not null references donation_allocations(id),amount_minor bigint not null check(amount_minor>0),description text not null,bank_reference text not null unique,evidence text not null,requested_by uuid not null references profiles(id),approved_by uuid references profiles(id),status text not null default 'requested' check(status in ('requested','approved')),created_at timestamptz not null default now(),check(approved_by is null or approved_by<>requested_by));
create table public.webhook_events(id uuid primary key default gen_random_uuid(),provider text not null,event_id text not null,body_hash text not null,received_at timestamptz not null default now(),unique(provider,event_id));
do $$ declare t text;begin foreach t in array array['suppliers','product_categories','catalog_products','product_variants','inventory','quotes','quote_lines','orders','order_items','order_events','shipments','customs_docs','disputes','recognition_preferences','transactions','transaction_events','donations','order_ledger_entries','donation_allocations','expenditures','webhook_events'] loop execute format('alter table %I enable row level security',t);end loop;end $$;
create policy categories_read on product_categories for select using(true);
create policy supplier_staff on suppliers for select to authenticated using(has_role(array['procurement_manager','super_admin','auditor']));
create policy product_staff on catalog_products for select to authenticated using(has_role(array['procurement_manager','super_admin','auditor']));
create view public_catalog_products with(security_barrier=true) as select p.id,p.sku,p.slug,p.title,c.slug as category_slug,c.name as category,p.partner_id,p.listing_type,p.specs,p.origin,p.condition,p.warranty,p.voltage,p.lead_time,p.currency,p.price_minor,p.price_valid_until,p.hs_code,p.import_eligibility,p.seller_of_record,p.importer_of_record,p.warranty_party,p.partner_roles,s.name as source_partner from catalog_products p join suppliers s on s.id=p.partner_id join product_categories c on c.id=p.category_id where p.status='published' and s.verification_status='verified';
create policy quote_read on quotes for select to authenticated using(customer_id=app_auth.uid() or has_role(array['procurement_manager','auditor']));
create policy quote_lines_read on quote_lines for select to authenticated using(exists(select 1 from quotes where id=quote_id));
create policy order_read on orders for select to authenticated using(buyer_id=app_auth.uid() or has_role(array['procurement_manager','finance_reviewer','finance_approver','auditor']));
create view supplier_assignments with(security_barrier=true) as select id,reference,status,source_partner_id,created_at from orders where assigned_supplier_user=app_auth.uid() and has_role(array['supplier']);
create policy items_read on order_items for select to authenticated using(exists(select 1 from orders where id=order_id) or exists(select 1 from supplier_assignments where id=order_id));
create policy order_events_read on order_events for select to authenticated using(exists(select 1 from orders where id=order_id));
create policy shipments_read on shipments for select to authenticated using(exists(select 1 from orders where id=order_id));
create policy customs_read on customs_docs for select to authenticated using(exists(select 1 from orders where id=order_id));
create policy disputes_read on disputes for select to authenticated using(owner_id=app_auth.uid() or has_role(array['procurement_manager','programme_manager','auditor']));
create policy recognition_own on recognition_preferences for select to authenticated using(user_id=app_auth.uid());
create policy recognition_insert on recognition_preferences for insert to authenticated with check(user_id=app_auth.uid());
create policy recognition_update on recognition_preferences for update to authenticated using(user_id=app_auth.uid()) with check(user_id=app_auth.uid());
create policy transaction_read on transactions for select to authenticated using(user_id=app_auth.uid() or has_role(array['finance_reviewer','finance_approver','auditor']));
create policy transaction_events_read on transaction_events for select to authenticated using(exists(select 1 from transactions where id=transaction_id));
create policy donations_read on donations for select to authenticated using(supporter_id=app_auth.uid() or has_role(array['finance_reviewer','finance_approver','auditor']));
create policy order_ledger_read on order_ledger_entries for select to authenticated using(has_role(array['finance_reviewer','finance_approver','auditor']));
create policy allocation_read on donation_allocations for select to authenticated using(has_role(array['finance_reviewer','finance_approver','programme_manager','auditor']));
create policy expenditure_read on expenditures for select to authenticated using(has_role(array['finance_reviewer','finance_approver','programme_manager','auditor']));
create view public_legacy_wall with(security_barrier=true) as select r.public_alias,r.city,r.message,r.recognition_type,min(d.created_at) as supporter_since from recognition_preferences r join donations d on d.supporter_id=r.user_id join transactions t on t.id=d.transaction_id where r.visibility='public' and d.recognition_visibility='public' and not exists(select 1 from transaction_events e where e.transaction_id=t.id and e.event_type='reversed') group by r.user_id,r.public_alias,r.city,r.message,r.recognition_type;
create view public_expenditures with(security_barrier=true) as select id,project_id,amount_minor,description,evidence,created_at from expenditures where status='approved';
do $$ declare t text;begin foreach t in array array['transactions','transaction_events','donations','order_ledger_entries','order_events','order_items'] loop execute format('create trigger immutable before update or delete on %I for each row execute function immutable()',t);end loop;end $$;
create function public.recognition_audit() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into consent_records(owner_id,title,status,data) values(app_auth.uid(),'Recognition preferences','submitted',jsonb_build_object('visibility',new.visibility,'previous_visibility',case when TG_OP='UPDATE' then old.visibility else null end,'at',now()));return new;end $$;
create trigger recognition_audit after insert or update on recognition_preferences for each row execute function recognition_audit();
create function public.create_donation(amount bigint,visibility text,dedication_text text,project uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare iid uuid;begin
 if visibility not in ('private','anonymous','public') or length(dedication_text)>500 then raise exception 'Invalid recognition settings';end if;
 if project is not null and not exists(select 1 from development_projects where id=project and status='published' and published_at<=now()) then raise exception 'Choose an approved published project';end if;
 iid:=create_intent(amount);update contribution_intents set dedication=dedication_text,recognition_visibility=visibility,restricted_project_id=project where id=iid;return iid;end $$;
create function public.request_quote(items jsonb,details text) returns uuid language plpgsql security definer set search_path=public as $$ declare qid uuid;item jsonb;begin
 if app_auth.uid() is null or length(details)<5 or jsonb_array_length(items)>30 then raise exception 'Invalid quotation request';end if;
 for item in select * from jsonb_array_elements(items) loop if not exists(select 1 from public_catalog_products where id=(item->>'product_id')::uuid) or (item->>'quantity')::int not between 1 and 10000 then raise exception 'Invalid product or quantity';end if;end loop;
 insert into quotes(customer_id,request_details,requested_items) values(app_auth.uid(),details,items) returning id into qid;
 insert into audit_events(actor_id,action,entity,entity_id) values(app_auth.uid(),'quote_requested','quotes',qid);return qid;end $$;
create function public.issue_quote(qid uuid,details jsonb,lines jsonb) returns void language plpgsql security definer set search_path=public as $$ declare q quotes;item jsonb;begin
 if not has_role(array['procurement_manager']) then raise exception 'Procurement role and MFA required';end if;
 select * into q from quotes where id=qid for update;if q.id is null or q.status not in ('requested','draft') or q.customer_id=app_auth.uid() then raise exception 'Invalid quotation or self-quotation';end if;
 if not exists(select 1 from suppliers where id=(details->>'supplier_id')::uuid and verification_status='verified') then raise exception 'Verified supplier required';end if;
 if (details->>'expires_at')::timestamptz<=now() or jsonb_array_length(lines)=0 then raise exception 'Valid expiry and order lines required';end if;
 update quotes set supplier_id=(details->>'supplier_id')::uuid,supplier_price=(details->>'supplier_price')::bigint,service_margin=(details->>'service_margin')::bigint,export_handling=(details->>'export_handling')::bigint,freight=(details->>'freight')::bigint,insurance=(details->>'insurance')::bigint,duties_taxes=(details->>'duties_taxes')::bigint,clearing=(details->>'clearing')::bigint,domestic_transport=(details->>'domestic_transport')::bigint,inspection=(details->>'inspection')::bigint,fx_rate=(details->>'fx_rate')::numeric,fx_source=details->>'fx_source',fx_at=(details->>'fx_at')::timestamptz,fx_risk_party=details->>'fx_risk_party',assumptions=details->>'assumptions',seller_of_record=details->>'seller_of_record',importer_of_record=details->>'importer_of_record',warranty_party=details->>'warranty_party',partner_roles=details->>'partner_roles',estimated_window=details->>'estimated_window',terms_version=details->>'terms_version',expires_at=(details->>'expires_at')::timestamptz,created_by=app_auth.uid(),status='draft' where id=qid;
 delete from quote_lines where quote_id=qid;
 for item in select * from jsonb_array_elements(lines) loop insert into quote_lines(quote_id,product_id,description,quantity,unit_price_minor) values(qid,nullif(item->>'product_id','')::uuid,item->>'description',(item->>'quantity')::int,(item->>'unit_price_minor')::bigint);end loop;
 if (select sum(quantity::bigint*unit_price_minor) from quote_lines where quote_id=qid)<>(select supplier_price from quotes where id=qid) then raise exception 'Order lines must match supplier product total';end if;
 insert into audit_events(actor_id,action,entity,entity_id) values(app_auth.uid(),'quote_priced','quotes',qid);end $$;
create function public.approve_quote(qid uuid) returns void language plpgsql security definer set search_path=public as $$ declare q quotes;begin
 if not has_role(array['procurement_manager']) then raise exception 'Procurement role required';end if;select * into q from quotes where id=qid for update;
 if q.id is null or q.status<>'draft' or q.created_by=app_auth.uid() or q.customer_id=app_auth.uid() then raise exception 'Independent price approval required';end if;
 if q.total_minor<100000 or q.expires_at<=now() or nullif(q.seller_of_record,'') is null or nullif(q.importer_of_record,'') is null or nullif(q.warranty_party,'') is null or nullif(q.partner_roles,'') is null or nullif(q.assumptions,'') is null or q.fx_rate<=0 or nullif(q.fx_source,'') is null or q.fx_at is null or nullif(q.fx_risk_party,'') is null or nullif(q.terms_version,'') is null then raise exception 'Complete pricing, FX, seller, import, warranty and terms disclosures';end if;
 update quotes set status='sent',approved_by=app_auth.uid() where id=qid;
 insert into notifications(owner_id,title,body) values(q.customer_id,'Your quotation is ready','Review the itemized landed costs, terms and expiry in your orders workspace.');
 insert into audit_events(actor_id,action,entity,entity_id) values(app_auth.uid(),'quote_approved','quotes',qid);end $$;
create function public.accept_quote(qid uuid,delivery_details jsonb,terms text) returns uuid language plpgsql security definer set search_path=public as $$ declare q quotes;oid uuid;aid uuid;iid uuid;gates jsonb;begin
 if app_auth.uid() is null then raise exception 'Sign in required';end if;
 select value into gates from platform_settings where key='commerce';if not coalesce((gates->>'enabled')::boolean,false) then raise exception 'Commerce checkout is not open yet';end if;
 select * into q from quotes where id=qid for update;
 if q.id is null or q.customer_id<>app_auth.uid() then raise exception 'Quotation access denied';end if;
 if q.status='accepted' then select id into oid from orders where quote_id=qid;return oid;end if;
 if q.status<>'sent' or q.expires_at<=now() or q.terms_version<>terms then raise exception 'A current approved quotation and matching terms are required';end if;
 if length(coalesce(delivery_details->>'address',''))<5 or length(coalesce(delivery_details->>'phone',''))<7 or length(coalesce(delivery_details->>'name',''))<2 then raise exception 'Complete delivery name, phone and address';end if;
 select id into aid from bank_accounts where approved limit 1;if aid is null then raise exception 'Approved corporate beneficiary required';end if;
 insert into orders(buyer_id,quote_id,seller_id,source_partner_id,total_minor,delivery,accepted_terms_version) values(app_auth.uid(),qid,q.supplier_id,q.supplier_id,q.total_minor,delivery_details,terms) returning id into oid;
 insert into order_items(order_id,product_id,description,quantity,unit_price_minor) select oid,product_id,description,quantity,unit_price_minor from quote_lines where quote_id=qid;
 insert into contribution_intents(owner_id,amount_minor,account_id,purpose,order_id) values(app_auth.uid(),q.total_minor,aid,'order',oid) returning id into iid;
 update quotes set status='accepted',accepted_at=now() where id=qid;
 insert into order_events(order_id,status,note,actor_id) values(oid,'payment_pending','Approved quote accepted. Availability and payment remain subject to verification.',app_auth.uid());
 insert into audit_events(actor_id,action,entity,entity_id) values(app_auth.uid(),'quote_accepted','orders',oid);return oid;end $$;
create function public.advance_order(oid uuid,next_status text,note_text text,supplier_user uuid default null) returns void language plpgsql security definer set search_path=public as $$ declare o orders;allowed text;begin
 if not has_role(array['procurement_manager']) or length(note_text)<5 then raise exception 'Procurement role and explanatory note required';end if;
 select * into o from orders where id=oid for update;if o.id is null or o.buyer_id=app_auth.uid() then raise exception 'Order access denied';end if;
 allowed:=case o.status when 'payment_verified' then 'procurement_approved' when 'procurement_approved' then 'purchased' when 'purchased' then 'inspection' when 'inspection' then 'in_transit' when 'in_transit' then 'clearance' when 'clearance' then 'delivery' when 'delivery' then 'completed' when 'failed_delivery' then 'delivery' else null end;
 if next_status is distinct from allowed and not (next_status='failed_delivery' and o.status='delivery') then raise exception 'Invalid fulfilment transition';end if;
 if supplier_user is not null and not exists(select 1 from role_assignments where user_id=supplier_user and role='supplier' and (expires_at is null or expires_at>now())) then raise exception 'Assigned user must have a supplier role';end if;
 update orders set status=next_status,assigned_supplier_user=coalesce(supplier_user,assigned_supplier_user) where id=oid;
 insert into order_events(order_id,status,note,actor_id) values(oid,next_status,note_text,app_auth.uid());
 insert into notifications(owner_id,title,body) values(o.buyer_id,'Order progress',note_text);
 insert into audit_events(actor_id,action,entity,entity_id,details) values(app_auth.uid(),'order_advanced','orders',oid,jsonb_build_object('from',o.status,'to',next_status));end $$;
create function public.open_dispute(oid uuid,kind_text text,reason_text text) returns uuid language plpgsql security definer set search_path=public as $$ declare did uuid;begin
 if length(reason_text)<5 or not exists(select 1 from orders where id=oid and buyer_id=app_auth.uid()) then raise exception 'Own order and reason required';end if;
 insert into disputes(order_id,owner_id,kind,reason) values(oid,app_auth.uid(),kind_text,reason_text) returning id into did;
 insert into order_events(order_id,status,note,actor_id) values(oid,'case_opened',kind_text||': '||reason_text,app_auth.uid());return did;end $$;
create function public.allocate_donation(did uuid,pid uuid,amount bigint,reason_text text) returns uuid language plpgsql security definer set search_path=public as $$ declare d donations;aid uuid;begin
 if not has_role(array['programme_manager']) then raise exception 'Programme manager required';end if;select * into d from donations where id=did for update;
 if d.id is null or (d.restricted_project_id is not null and d.restricted_project_id<>pid) then raise exception 'Respect donor project restrictions';end if;
 if amount<=0 or amount+coalesce((select sum(amount_minor) from donation_allocations where donation_id=did),0)>d.amount_minor or exists(select 1 from transaction_events where transaction_id=d.transaction_id and event_type='reversed') then raise exception 'Insufficient unallocated verified funds';end if;
 insert into donation_allocations(donation_id,project_id,amount_minor,reason,requested_by) values(did,pid,amount,reason_text,app_auth.uid()) returning id into aid;return aid;end $$;
create function public.approve_allocation(aid uuid) returns void language plpgsql security definer set search_path=public as $$ begin
 if not has_role(array['finance_approver']) then raise exception 'Finance approver required';end if;
 update donation_allocations set status='approved',approved_by=app_auth.uid() where id=aid and status='requested' and requested_by<>app_auth.uid();if not found then raise exception 'Independent approval required';end if;
